import { CSSTransition } from "react-transition-group";
import "./ModalBase.css"
import { useMemo } from "react";
import { createTheme, ThemeProvider, Button, Dialog, DialogActions, DialogContent, DialogTitle, Box } from "@mui/material";
import { theme } from "../../themes/Theme.ts";

function ModalBase(props) {
    const mode = localStorage.getItem("website_theme");
    const themeMode = useMemo(() => createTheme(theme(mode)), [mode]);

    return (
        <ThemeProvider theme={themeMode}>
            <Dialog open={props.show} fullWidth>
                <DialogTitle>
                    <Box sx={{display: "flex", alignItems: "center", justifyContent: "space-between"}}>
                        {props.title}
                        <Button onClick={props.onClose}>
                            Fechar
                        </Button>
                    </Box>
                </DialogTitle>
                <DialogContent>
                    {props.children}
                </DialogContent>
                <DialogActions>
                    <Button autoFocus form={props.formName} type="submit">
                        Salvar
                    </Button>
                </DialogActions>
            </Dialog>
        </ThemeProvider>
    )
}

export default ModalBase