import { PaletteMode } from "@mui/material";
import { blue, brown, green, grey, red } from "@mui/material/colors";

export const theme = (mode: PaletteMode) => ({
  palette: {
    mode,
    ...(mode === "light"
      ? {
          primary: {
            main: blue[900],
          },
          secondary: {
            main: "#E8F7FB",
          },

          background: {
            primary: "#f5f5f5",
            secondary: "#ffffff",
          },

          text: {
            primary: "#000000",
            secondary: "#808080",
            white: {
              main: "#FFFFFF",
            },
          },
          button: {
            primary: {
              main: "#000000",
            },
          },
        }
      : {
          primary: {
            main: blue[500],
          },
          secondary: {
            main: "#E8F7FB",
          },

          background: {
            primary: "#212121",
            secondary: "#262626",
          },

          text: {
            primary: "#FFFFFF",
            secundary: "#424242",
            white: "#FFFFFF",
          },
        }),
  },
});
