import {Outlet} from "react-router-dom";
import {Box} from "@mui/system";
import MenuSide from "./MenuSide";
import AppBarDefault from "./AppBarDefault";
import {AppBarButtonContext} from "../context/AppBarButtonContext";
import React, {useMemo} from "react";
import {useState} from "react";
import {useTheme} from "@emotion/react";

const DefaultPage = ({ColorModeContext}) => {
    const [actionButton, setActionButton] = useState(() => {
    });
    const theme = useTheme()

    document.querySelector("body").style.backgroundColor = theme?.palette?.background?.primary ?? ''

    const setActionAppBarButton = useMemo(() => ({
        changeActionAppBarButtonOnClick: (value) => {
            setActionButton(value)
        }
    }))

    return (
        <Box sx={{display: "flex", flexDirection: "row"}}>
            <MenuSide/>
            <Box sx={{display: "grid", width: "100%"}}>
                <AppBarButtonContext.Provider value={setActionAppBarButton}>
                    <AppBarDefault onClickActionButton={actionButton} ColorModeContext={ColorModeContext}/>
                    <Outlet/>
                </AppBarButtonContext.Provider>
            </Box>
        </Box>
    );
}

export default DefaultPage;
