import http from "../../../HttpHelper";

class AuthenticationRepository {
  async login(login, password) {
    const response = await http.post("/auth/login", {
      username: login,
      password: password,
    });
    localStorage.setItem("user", JSON.stringify(response.data));
    return response.data;
  }

  /**
   * Call the logout endpoint, responsible for clearing the authentication status
   */
  async logout() {
    await http.post("/auth/logout");
    localStorage.removeItem("user");
  }

  async requestPasswordReset(email) {
    const response = await http.post("/auth/requestPasswordReset", {
      email: email,
    });
    return response.data;
  }

  async changePassword(currentPassword, newPassword, confirmPassword) {
    const response = await http.post("/user/updatePassword", {
      currentPassword: currentPassword,
      newPassword: newPassword,
      newPasswordConfirmation: confirmPassword,
    });
    return response.data;
  }

  async resetPassword(password, passwordConfirmation, requesID) {
    const response = await http.post(`/auth/passwordReset/${requesID}`, {
      password: password,
      passwordConfirmation: passwordConfirmation,
    });
    return response.data;
  }  

  async isUserLoggedIn() {
    const rawUser = localStorage.getItem("user");
    const user = JSON.parse(rawUser);    
    const response = await http.get(`/user/${user.authenticationRecord}`);
    console.log(response)
    return response;
  }

  // async verifyLoginUser(){
  //   const response = http.get("")
  // }
}

export default new AuthenticationRepository();
