import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useForm } from "react-hook-form";
import AuthenticationUseCase from "../../usecases/authentication_usecase";
import {
  Box,
  FormControl,
  IconButton,
  Paper,
  TextField,
  Typography,
  useTheme,
} from "@mui/material";
import Visibility from "@mui/icons-material/Visibility";
import VisibilityOff from "@mui/icons-material/VisibilityOff";
import Swal from "sweetalert2";
import { LoadingButton } from "@mui/lab";

const ToastFailed = Swal.mixin({
  toast: true,
  position: "top-end",
  showConfirmButton: false,
  timer: 3000,
  timerProgressBar: true,
  didOpen: (toast) => {
    toast.addEventListener("mouseenter", Swal.stopTimer);
    toast.addEventListener("mouseleave", Swal.resumeTimer);
  },
});

const Login = () => {
  const navigate = useNavigate();
  const { handleSubmit, setError, register, formState } = useForm();
  const { errors } = formState;
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [disabled, setDisabled] = useState(false);

  const theme = useTheme();

  const handleLogin = async (data) => {
    setLoading(true);
    setDisabled(true);

    try {
      const response = await AuthenticationUseCase.login(
        data.user,
        data.password
      );
      if (response.isPasswordExpired) {
        navigate("/ChangePasswordLogin");

        return;
      }
      setLoading(false);
      setDisabled(false);
      ToastFailed.fire({
        icon: "success",
        title: "Login successful",
      });
      navigate("/payment");
    } catch (error) {
      var message = "";

      console.log(error?.response);

      if (error?.response?.data?.message) {
        message = error?.response?.data?.message;
      } else {
        message = "An unexpected error occurred!";
      }

      if (
        message ===
        "UserDetailsService returned null, which is an interface contract violation"
      ) {
        setError("user", { type: "custom", message: "Invalid user" });
      }

      if (message === "Bad credentials") {
        setError("password", { type: "custom", message: "Invalid password" });
      }

      ToastFailed.fire({
        icon: "error",
        title: message,
      });

      setLoading(false);
      setDisabled(false);
    }
  };

  const handleClickShowPassword = () => setShowPassword((show) => !show);

  const handleMouseDownPassword = (event) => {
    event.preventDefault();
  };

  useEffect(() => {
    document.title = "Lince Tech Micro ERP | Login";
  }, []);

  return (
    <Box
      sx={{
        display: "flex",
        width: "100vw",
        height: "100vh",
        backgroundColor: "background.primary",
      }}
    >
      <Paper
        className="bg-image"
        variant="outlined"
        sx={{
          width: { xl: "55%", md: "45%" },
          display: { xl: "flex", md: "flex", xs: "none" },
        }}
      ></Paper>
      <Box
        sx={{
          backgroundColor: "background.primary",
          zIndex: "999",
          width: { xl: "45%", md: "55%", xs: "100%" },
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <Box
          component="form"
          sx={{
            display: "flex",
            justifyContent: "center",
            height: { xl: "60%", lg: "60%", md: "65%", sm: "75%", xs: "80%" },
            width: { xl: "55%", lg: "55%", md: "65%", sm: "75%", xs: "95%" },
          }}
          onSubmit={handleSubmit(handleLogin)}
          noValidate
        >
          <Paper
            elevation={5}
            sx={{
              borderRadius: "15px",
              display: "flex",
            }}
          >
            <Box
              sx={{
                display: "grid",
                alignContent: "space-between",
                padding: "3rem",
              }}
            >
              <Box>
                <Typography
                  sx={{
                    fontSize: {
                      xl: "20pt",
                      lg: "20pt",
                      md: "20pt",
                      sm: "20pt",
                      xs: "20pt",
                    },
                    fontWeight: "bold",
                  }}
                >
                  LOGIN
                </Typography>
                {/* <Box
                  sx={{
                    width: "2rem",
                    padding: "3px",
                    borderRadius: "8px",
                    background:
                      "linear-gradient(90deg, #127392 0%, #1686A9 35%, #1C9FC8 100%)",
                  }}
                ></Box> */}
              </Box>
              <Typography
                sx={{
                  fontSize: {
                    xl: "11pt",
                    lg: "11pt",
                    md: "11pt",
                    sm: "11pt",
                    sx: "11pt",
                  },
                  fontWeight: "400",
                }}
              >
                Hello, we're glad you're here, please enter your email and
                password to login.
              </Typography>
              <TextField
                sx={{ height: "4rem" }}
                label="User"
                autoFocus
                variant="outlined"
                disabled={disabled}
                error={errors?.user?.message}
                helperText={errors?.user?.message}
                {...register("user", {
                  required: "User is required!",
                  maxLength: { value: 32, message: "Too many characters!" },
                })}
              />

              <FormControl variant="outlined">
                <TextField
                  sx={{ height: "4rem" }}
                  autoComplete="current-password"
                  label="Password"
                  disabled={disabled}
                  type={showPassword ? "text" : "password"}
                  error={errors?.password?.message}
                  helperText={errors?.password?.message}
                  {...register("password", {
                    required: "Password is required!",
                    minLength: {
                      value: 1,
                      message: "Password is too short!",
                    },
                    maxLength: { value: 32, message: "Too many characters!" },
                  })}
                ></TextField>

                <IconButton
                  aria-label="toggle password visibility"
                  onClick={handleClickShowPassword}
                  onMouseDown={handleMouseDownPassword}
                  disabled={disabled}
                  sx={{
                    position: "absolute",
                    right: "0.5rem",
                    bottom: "1rem",
                    top: "1rem",
                  }}
                >
                  {showPassword ? <VisibilityOff /> : <Visibility />}
                </IconButton>
              </FormControl>
              <LoadingButton
                type="submit"
                size="medium"
                loading={loading}
                loadingPosition="end"
                variant="contained"
                sx={{
                  fontSize: {
                    xl: "13pt",
                    lg: "13pt",
                    md: "13pt",
                    sm: "13pt",
                    sx: "12pt",
                  },
                  height: "3rem",
                }}
              >
                <span>Login</span>
              </LoadingButton>

              <Box sx={{ display: "flex", gap: "0.5rem" }}>
                <Typography
                  color={"gray"}
                  sx={{
                    fontSize: {
                      xl: "11pt",
                      lg: "11pt",
                      md: "11pt",
                      sm: "11pt",
                      sx: "11pt",
                    },
                    fontWeight: "400",
                  }}
                >
                  Forgot password?
                </Typography>
                <Typography
                  sx={{
                    fontSize: {
                      xl: "11pt",
                      lg: "11pt",
                      md: "11pt",
                      sm: "11pt",
                      sx: "11pt",
                    },
                    fontWeight: "bold",
                  }}
                >
                  <Link
                    style={{
                      textDecoration: "none",
                      color: theme.palette.mode === "dark" ? "#FFF" : "#000",
                      fontWeight: "bold",
                    }}
                    to="/ResetPassword?step=1"
                  >
                    Click Here!
                  </Link>
                </Typography>
              </Box>
            </Box>
          </Paper>
        </Box>
      </Box>
    </Box>
  );
};
export default Login;
