export class Payment {
    /**
     * @param uuid {string}
     * @param type {PaymentType}
     * @param value {number}
     * @param description {string}
     * @param date {Date}
     * */
    constructor(uuid, type, value, description, date) {
        this.uuid = uuid;
        this.date = date;
        this.description = description;
        this.type = type;
        this.value = value;
    }
}

export class PaymentType {
    /**
     * @param uuid {string}
     * @param code {int}
     * @param description {string}
     * */
    constructor(uuid, code, description) {
        this.uuid = uuid;
        this.code = code;
        this.description = description;
    }

}