import {useState, useMemo} from "react";
import {Link, useLocation, useNavigate} from "react-router-dom";
import VisibilityOff from "@mui/icons-material/VisibilityOff";
import Visibility from "@mui/icons-material/Visibility";
import AuthenticationRepository from "../../repositories/authentication_repository";
import {useForm} from "react-hook-form";
import {
    Box,
    CircularProgress,
    FormControl,
    IconButton,
    Paper,
    TextField,
    Typography,
} from "@mui/material";
import Swal from "sweetalert2";
import {LoadingButton} from "@mui/lab";

const ToastFailed = Swal.mixin({
    toast: true,
    position: "top-end",
    showConfirmButton: false,
    timer: 3000,
    timerProgressBar: true,
    didOpen: (toast) => {
        toast.addEventListener("mouseenter", Swal.stopTimer);
        toast.addEventListener("mouseleave", Swal.resumeTimer);
    },
});

function useQuery() {
    const {search} = useLocation();
    return useMemo(() => new URLSearchParams(search), [search]);
}

const ResetPassword = () => {
    const navigate = useNavigate();
    const {handleSubmit, register, formState} = useForm();
    const {errors} = formState;
    const [loading, setLoading] = useState(false);
    const [showNewPassword, setShowNewPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [disabled, setDisabled] = useState(false);
    const query = useQuery();

    const handleClickShowNewPassword = () => setShowNewPassword((show) => !show);

    const handleMouseDownNewPassword = (event) => {
        event.preventDefault();
    };

    const handleClickShowConfirmPassword = () =>
        setShowConfirmPassword((show) => !show);

    const handleMouseDownConfirmPassword = (event) => {
        event.preventDefault();
    };

    const handleChangePassword = async (data) => {
        setLoading(true);
        setDisabled(true);

        const requestID = query.get("requestID");

        try {
            if (data.newPassword == data.confirmPassword) {
                const response = await AuthenticationRepository.resetPassword(
                    data.newPassword,
                    data.confirmPassword,
                    requestID
                );

                if (response?.error?.description) {
                    ToastFailed.fire({
                        icon: "error",
                        title: response?.error?.description,
                    });

                    setLoading(false);
                    setDisabled(false);
                } else {
                    navigate("/login");

                    setLoading(false);
                    setDisabled(false);

                    ToastFailed.fire({
                        icon: "success",
                        title: "Your password has been changed successfully.",
                    });
                }
            } else {
                ToastFailed.fire({
                    icon: "error",
                    title: "Please make sure your passwords match.",
                });

                setLoading(false);
                setDisabled(false);
            }
        } catch (error) {
            var message = "";

            if (error?.response?.description) {
                message = error?.response?.description;
            } else {
                message = "An unexpected error occurred!";
            }

            ToastFailed.fire({
                icon: "error",
                title: message,
            });

            setLoading(false);
            setDisabled(false);
        }
    };

    return (
        <Box sx={{display: "flex", width: "100vw", height: "100vh"}}>
            <Box
                sx={{
                    backgroundColor: "#f8f8f8",
                    zIndex: "999",
                    width: {xl: "45%", md: "55%", xs: "100%"},
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                }}
            >
                <Box
                    component="form"
                    sx={{
                        display: "flex",
                        justifyContent: "center",
                        height: {xl: "52%", lg: "52%", md: "65%", sm: "65%", xs: "65%"},
                        width: {xl: "55%", lg: "55%", md: "65%", sm: "75%", xs: "95%"},
                    }}
                    onSubmit={handleSubmit(handleChangePassword)}
                    noValidate
                >
                    <Paper
                        elevation={2}
                        sx={{
                            backgroundColor: "white",
                            borderRadius: "15px",
                            display: "flex",
                            width: "100%",
                        }}
                    >
                        <Box
                            sx={{
                                display: "grid",
                                alignContent: "space-between",
                                padding: "3rem",
                                width: "100%",
                            }}
                        >
                            <Box>
                                <Typography
                                    sx={{
                                        fontSize: {
                                            xl: "18pt",
                                            lg: "20pt",
                                            md: "18pt",
                                            sm: "18pt",
                                            sx: "18pt",
                                        },
                                        fontWeight: "bold",
                                    }}
                                >
                                    Change Password
                                </Typography>
                            </Box>

                            <Typography
                                sx={{
                                    fontSize: {
                                        xl: "11pt",
                                        lg: "11pt",
                                        md: "11pt",
                                        sm: "11pt",
                                        sx: "11pt",
                                    },
                                    fontWeight: "400",
                                }}
                            >
                                Do you forget your password? Insert your new password.
                            </Typography>

                            <FormControl variant="outlined">
                                <TextField
                                    sx={{height: "4rem"}}
                                    autoComplete="current-password"
                                    label="New Password"
                                    id="outlined-adornment-password"
                                    disabled={disabled}
                                    type={showNewPassword ? "text" : "password"}
                                    error={errors?.newPassword?.message}
                                    helperText={errors?.newPassword?.message}
                                    {...register("newPassword", {
                                        required: "Password is required!",
                                        minLength: {
                                            value: 1,
                                            message: "Password is too short!",
                                        },
                                        maxLength: {value: 32, message: "Too many characters!"},
                                    })}
                                ></TextField>

                                <IconButton
                                    aria-label="toggle password visibility"
                                    onClick={handleClickShowNewPassword}
                                    onMouseDown={handleMouseDownNewPassword}
                                    disabled={disabled}
                                    sx={{
                                        position: "absolute",
                                        right: "0.5rem",
                                        bottom: "1rem",
                                        top: "1rem",
                                    }}
                                >
                                    {showNewPassword ? <VisibilityOff/> : <Visibility/>}
                                </IconButton>
                            </FormControl>
                            <FormControl variant="outlined">
                                <TextField
                                    sx={{height: "4rem"}}
                                    autoComplete="current-password"
                                    label="Confirm New Password"
                                    disabled={disabled}
                                    type={showConfirmPassword ? "text" : "password"}
                                    error={errors?.confirmPassword?.message}
                                    helperText={errors?.confirmPassword?.message}
                                    {...register("confirmPassword", {
                                        required: "Password is required!",
                                        minLength: {
                                            value: 1,
                                            message: "Password is too short!",
                                        },
                                        maxLength: {value: 32, message: "Too many characters!"},
                                    })}
                                ></TextField>
                                <IconButton
                                    aria-label="toggle password visibility"
                                    onClick={handleClickShowConfirmPassword}
                                    onMouseDown={handleMouseDownConfirmPassword}
                                    disabled={disabled}
                                    sx={{
                                        position: "absolute",
                                        right: "0.5rem",
                                        bottom: "1rem",
                                        top: "1rem",
                                    }}
                                >
                                    {showConfirmPassword ? <VisibilityOff/> : <Visibility/>}
                                </IconButton>
                            </FormControl>

                            <LoadingButton
                                type="submit"
                                size="small"
                                loading={loading}
                                loadingPosition="end"
                                variant="contained"
                                loadingIndicator={
                                    <CircularProgress size={25} color="inherit"/>
                                }
                                sx={{
                                    fontSize: {
                                        xl: "13pt",
                                        lg: "13pt",
                                        md: "13pt",
                                        sm: "13pt",
                                        sx: "12pt",
                                    },
                                    height: "3.5rem",
                                }}
                            >
                                <span>Change Password</span>
                            </LoadingButton>
                            <Box sx={{display: "flex", gap: "0.5rem"}}>
                                <Typography
                                    sx={{
                                        fontSize: {
                                            xl: "11pt",
                                            lg: "11pt",
                                            md: "11pt",
                                            sm: "11pt",
                                            sx: "11pt",
                                        },
                                    }}
                                >
                                    Go back to
                                </Typography>
                                <Typography
                                    sx={{
                                        fontSize: {
                                            xl: "11pt",
                                            lg: "11pt",
                                            md: "11pt",
                                            sm: "11pt",
                                            sx: "11pt",
                                        },
                                        fontWeight: "bold",
                                    }}
                                >
                                    <Link
                                        style={{
                                            textDecoration: "none",
                                            color: "black",
                                            fontWeight: "bold",
                                        }}
                                        to="/login"
                                    >
                                        Sign In!
                                    </Link>
                                </Typography>
                            </Box>
                        </Box>
                    </Paper>
                </Box>
            </Box>
            <Paper
                className="bg-image-3"
                variant="outlined"
                sx={{
                    width: {xl: "55%", md: "45%"},
                    display: {xl: "flex", md: "flex", xs: "none"},
                }}
            ></Paper>
        </Box>
    );
};
export default ResetPassword;
