import { useState, useMemo } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import AuthenticationUseCase from "../../usecases/authentication_usecase";
import { useForm } from "react-hook-form";
import {
  Box,
  CircularProgress,
  Paper,
  TextField,
  Typography,
} from "@mui/material";
import Swal from "sweetalert2";
import { LoadingButton } from "@mui/lab";

const ToastFailed = Swal.mixin({
  toast: true,
  position: "bottom-end",
  showConfirmButton: false,
  timer: 3000,
  timerProgressBar: true,
  didOpen: (toast) => {
    toast.addEventListener("mouseenter", Swal.stopTimer);
    toast.addEventListener("mouseleave", Swal.resumeTimer);
  },
});

function useQuery() {
  const { search } = useLocation();
  return useMemo(() => new URLSearchParams(search), [search]);
}

const ResetPassword = () => {
  const navigate = useNavigate();
  const { handleSubmit, register, formState } = useForm();
  const { errors } = formState;
  const [loading, setLoading] = useState(false);
  const query = useQuery();
  const [disabled, setDisabled] = useState(false);

  const handleResetPassword = async (data) => {
    setLoading(true);
    setDisabled(true);
    try {
      const response = await AuthenticationUseCase.resetPassword(data.email);
      setLoading(false);
      navigate("/ResetPassword?step=2");
    } catch (error) {
      var message = "";

      if (error?.response?.data?.message) {
        message = error?.response?.data?.message;
      } else {
        message = "An unexpected error occurred!";
      }

      ToastFailed.fire({
        icon: "error",
        title: message,
      });

      setLoading(false);
      setDisabled(false);
    }
  };

  const handleBackToLogin = async () => {
    navigate("/login");
  };

  return (
    <Box sx={{ display: "flex", width: "100vw", height: "100vh" }}>
      <Box
        sx={{
          backgroundColor: "#f8f8f8",
          zIndex: "999",
          width: { xl: "45%", md: "55%", xs: "100%" },
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {query.get("step") == 1 ? (
          <Box
            component="form"
            sx={{
              display: "flex",
              justifyContent: "center",
              height: { xl: "55%", lg: "55%", md: "65%", sm: "65%", xs: "65%" },
              width: { xl: "55%", lg: "55%", md: "65%", sm: "75%", xs: "95%" },
            }}
            onSubmit={handleSubmit(handleResetPassword)}
            noValidate
          >
            <Paper
              elevation={2}
              sx={{
                backgroundColor: "white",
                borderRadius: "15px",
                display: "flex",
              }}
            >
              <Box
                sx={{
                  display: "grid",
                  alignContent: "space-between",
                  padding: "3rem",
                }}
              >
                <Box>
                  <Typography
                    sx={{
                      fontSize: {
                        xl: "18pt",
                        lg: "20pt",
                        md: "18pt",
                        sm: "18pt",
                        sx: "18pt",
                      },
                      fontWeight: "bold",
                    }}
                  >
                    Reset password
                  </Typography>
                </Box>
                <Typography
                  sx={{
                    fontSize: {
                      xl: "11pt",
                      lg: "11pt",
                      md: "11pt",
                      sm: "11pt",
                      sx: "11pt",
                    },
                    fontWeight: "400",
                  }}
                >
                  Enter the email address associated with your account and we'll
                  send you a link to reset your password.
                </Typography>
                <Typography
                  sx={{
                    fontSize: {
                      xl: "11pt",
                      lg: "11pt",
                      md: "11pt",
                      sm: "11pt",
                      sx: "11pt",
                    },
                    fontWeight: "400",
                  }}
                >
                  If you don't have an email, contact an administrator.
                </Typography>

                <TextField
                  sx={{ height: "4rem" }}
                  label="Email"
                  autoFocus
                  variant="outlined"
                  disabled={disabled}
                  error={errors?.email?.message}
                  helperText={errors?.email?.message}
                  {...register("email", {
                    required: "Email is required!",
                    pattern: {
                      value: /\S+@\S+\.\S+/,
                      message: "Entered value does not match email format",
                    },
                  })}
                />

                <LoadingButton
                  type="submit"
                  size="small"
                  // onClick={handleClick}
                  loading={loading}
                  loadingPosition="end"
                  variant="contained"
                  loadingIndicator={
                    <CircularProgress size={25} color="inherit" />
                  }
                  sx={{
                    fontSize: {
                      xl: "13pt",
                      lg: "13pt",
                      md: "13pt",
                      sm: "13pt",
                      sx: "12pt",
                    },
                    height: "3.5rem",
                  }}
                >
                  <span>Send Email</span>
                </LoadingButton>
                <Box sx={{ display: "flex", gap: "0.5rem" }}>
                  <Typography
                    sx={{
                      fontSize: {
                        xl: "11pt",
                        lg: "11pt",
                        md: "11pt",
                        sm: "11pt",
                        sx: "11pt",
                      },
                    }}
                  >
                    Go back to
                  </Typography>
                  <Typography
                    sx={{
                      fontSize: {
                        xl: "11pt",
                        lg: "11pt",
                        md: "11pt",
                        sm: "11pt",
                        sx: "11pt",
                      },
                      fontWeight: "bold",
                    }}
                  >
                    <Link
                      style={{
                        textDecoration: "none",
                        color: "black",
                        fontWeight: "bold",
                      }}
                      to="/login"
                    >
                      Sign In!
                    </Link>
                  </Typography>
                </Box>
              </Box>
            </Paper>
          </Box>
        ) : (
          <Box
            component="form"
            sx={{
              display: "flex",
              justifyContent: "center",
              height: { xl: "55%", lg: "55%", md: "65%", sm: "70%", xs: "70%" },
              width: { xl: "55%", lg: "55%", md: "65%", sm: "75%", xs: "95%" },
            }}
            onSubmit={handleSubmit(handleResetPassword)}
            noValidate
          >
            <Paper
              elevation={5}
              sx={{
                backgroundColor: "white",
                borderRadius: "15px",
                display: "flex",
              }}
            >
              <Box
                sx={{
                  display: "grid",
                  alignContent: "space-between",
                  padding: "3rem",
                }}
              >
                <Box>
                  <Typography
                    sx={{
                      fontSize: {
                        xl: "18pt",
                        lg: "20pt",
                        md: "18pt",
                        sm: "18pt",
                        sx: "18pt",
                      },
                      fontWeight: "bold",
                    }}
                  >
                    Email Sent
                  </Typography>
                </Box>

                <Box
                  sx={{
                    width: "100%",
                    display: "flex",
                    justifyContent: "center",
                  }}
                >
                  <CheckCircleIcon sx={{ width: "100px", height: "100px" }} />
                </Box>

                <Typography
                  sx={{
                    textAlign: "center",
                    fontSize: {
                      xl: "11pt",
                      lg: "11pt",
                      md: "11pt",
                      sm: "11pt",
                      sx: "11pt",
                    },
                    fontWeight: "400",
                  }}
                >
                  Please check your inbox and click in the received link to
                  reset your password.
                </Typography>

                <LoadingButton
                  type="submit"
                  size="small"
                  onClick={handleBackToLogin}
                  loading={loading}
                  loadingPosition="end"
                  variant="contained"
                  sx={{
                    fontSize: {
                      xl: "13pt",
                      lg: "13pt",
                      md: "13pt",
                      sm: "13pt",
                      sx: "12pt",
                    },
                    height: "3.5rem",
                  }}
                >
                  <span>Return to Sign In</span>
                </LoadingButton>
                <Box sx={{ display: "flex", gap: "0.5rem" }}>
                  <Typography
                    color={"gray"}
                    sx={{
                      fontSize: {
                        xl: "11pt",
                        lg: "11pt",
                        md: "11pt",
                        sm: "11pt",
                        sx: "11pt",
                      },
                      fontWeight: "400",
                    }}
                  >
                    Didn't received the link?
                  </Typography>
                  <Typography
                    sx={{
                      fontSize: {
                        xl: "11pt",
                        lg: "11pt",
                        md: "11pt",
                        sm: "11pt",
                        sx: "11pt",
                      },
                      fontWeight: "bold",
                    }}
                  >
                    <Link
                      style={{
                        textDecoration: "none",
                        color: "black",
                        fontWeight: "bold",
                      }}
                      to="/ResetPassword?step=1"
                    >
                      Resend!
                    </Link>
                  </Typography>
                </Box>
              </Box>
            </Paper>
          </Box>
        )}
      </Box>
      <Paper
        className="bg-image-2"
        variant="outlined"
        sx={{
          width: { xl: "55%", md: "45%" },
          display: { xl: "flex", md: "flex", xs: "none" },
        }}
      >
        {/* <img src={background}></img> */}
      </Paper>
    </Box>
  );
};
export default ResetPassword;
