import {styled} from "@mui/material/styles";
import Box from "@mui/material/Box";
import MuiDrawer from "@mui/material/Drawer";
import List from "@mui/material/List";
import CssBaseline from "@mui/material/CssBaseline";
import Typography from "@mui/material/Typography";
import ListItem from "@mui/material/ListItem";
import ListItemButton from "@mui/material/ListItemButton";
import ListItemIcon from "@mui/material/ListItemIcon";
import ListItemText from "@mui/material/ListItemText";
import {useLocation, useNavigate} from "react-router-dom";
import IconButton from "@mui/material/IconButton";
import {Collapse, Tooltip} from "@mui/material";
import ExpandLess from "@mui/icons-material/ExpandLess";
import ExpandMore from "@mui/icons-material/ExpandMore";
import {icons as Icons} from "../entities/Icons";
import {useState} from "react";
import {useEffect} from "react";

import HomeOutlinedIcon from "@mui/icons-material/HomeOutlined";
import PaymentsOutlinedIcon from "@mui/icons-material/PaymentsOutlined";
import SortOutlinedIcon from "@mui/icons-material/SortOutlined";
import MoreVertOutlinedIcon from "@mui/icons-material/MoreVertOutlined";

const drawerWidth = 240;

const MenuModules = [
    {
        icon: <HomeOutlinedIcon/>,
        selectedIcon: <PaymentsOutlinedIcon color="primary"/>,
        route: "/payment",
        label: "Payment",
        routes: [],
        expanded: false,
    },
    {
        icon: <HomeOutlinedIcon/>,
        selectedIcon: <HomeOutlinedIcon color="primary"/>,
        route: "/statistics",
        label: "Statistics",
        routes: [],
        expanded: false,
    },
    // {
    //     icon: <Inventory2OutlinedIcon/>,
    //     selectedIcon: <Inventory2OutlinedIcon color="primary"/>,
    //     route: "",
    //     label: "Stock",
    //     expanded: true,
    //     routes: [
    //         {
    //             icon: <InventoryOutlinedIcon/>,
    //             selectedIcon: <InventoryOutlinedIcon color="primary"/>,
    //             route: "/Stock",
    //             label: "Stock",
    //             routes: [],
    //             expanded: false,
    //         },
    //         {
    //             icon: <CompareArrowsOutlinedIcon/>,
    //             selectedIcon: <CompareArrowsOutlinedIcon color="primary"/>,
    //             route: "/RequestHistory",
    //             label: "Request history",
    //             routes: [],
    //             expanded: false,
    //         }
    //     ],
    // },
]

const openedMixin = (theme) => ({
    width: drawerWidth,
    transition: theme.transitions.create("width", {
        easing: theme.transitions.easing.sharp,
        duration: theme.transitions.duration.enteringScreen,
    }),
    overflowX: "hidden",
});

const closedMixin = (theme) => ({
    transition: theme.transitions.create("width", {
        easing: theme.transitions.easing.sharp,
        duration: theme.transitions.duration.leavingScreen,
    }),
    overflowX: "hidden",
    width: `calc(${theme.spacing(7)} + 1px)`,
    [theme.breakpoints.up("sm")]: {
        width: `calc(${theme.spacing(8)} + 1px)`,
    },
});

const Drawer = styled(MuiDrawer, {
    shouldForwardProp: (prop) => prop !== "open",
})(
    ({theme, open}) => (
        console.log(theme),
            {
                width: drawerWidth,
                flexShrink: 0,
                whiteSpace: "nowrap",
                boxSizing: "border-box",
                ...(open && {
                    ...openedMixin(theme),
                    "& .MuiDrawer-paper": openedMixin(theme),
                }),
                ...(!open && {
                    ...closedMixin(theme),
                    "& .MuiDrawer-paper": closedMixin(theme),
                }),
            }
    )
);

const DrawerHeader = styled("div")(({theme}) => ({
    display: "flex",
    alignItems: "center",
    justifyContent: "flex-end",
    padding: theme.spacing(0, 1),
    ...theme.mixins.toolbar,
}));

const MenuSide = () => {
    const [open, setOpen] = useState(
        localStorage.getItem("drawerOpen") !== null
            ? JSON.parse(localStorage.getItem("drawerOpen"))
            : true
    );
    useEffect(() => {
        localStorage.setItem("drawerOpen", open);
    }, [open]);


    return (
        <Box sx={{display: "flex"}}>
            <CssBaseline/>
            <Drawer
                variant="permanent"
                open={open}
                PaperProps={{
                    sx: {
                        color: "#000",
                    },
                }}
                sx={{
                    "& .MuiDrawer-paper": {
                        display: "grid",
                        gridTemplateRows: "auto 1fr auto",
                        gridTemplateAreas: "'header' 'main' 'footer'",
                    },
                }}
            >
                <DrawerHeader
                    sx={{
                        gridArea: "header",
                        display: "flex",
                        justifyContent: open ? "space-between" : "center",
                        alignItems: "center",
                    }}
                >
                    {open ? (
                        <Box sx={{
                            marginLeft: "10px",
                            display: "flex",
                            alignItems: "center",
                            gap: "5px"
                        }}>
                            <Icons.logoPaymentBase64 width={"40px"}/>
                            <Typography sx={{
                                fontSize: "14pt",
                                fontWeight: "bold",
                            }}>
                                My payments
                            </Typography>
                        </Box>
                    ) : (
                        ""
                    )}
                    <IconButton onClick={() => setOpen(!open)}>
                        {open ? <SortOutlinedIcon/> : <MoreVertOutlinedIcon/>}
                    </IconButton>
                </DrawerHeader>
                <List sx={{display: "flex", flexDirection: "column", p: 2}}>
                    {MenuModules.map((module, index) => (
                        <ModuleList key={index} module={module} isDrawerOpen={open}/>
                    ))}
                </List>
            </Drawer>
        </Box>
    );
};

const ModuleList = ({module, isDrawerOpen}) => {
    const [openRoutes, setOpenRoutes] = useState(false);
    const selectedPage = useLocation().pathname;
    const navigate = useNavigate();

    const handleNavigate = (route) => {
        if (route !== "") {
            navigate(route);
        }
    };

    return (
        <ListItem
            sx={{
                display: "flex",
                flexDirection: "column",
                width: "100%",
                p: 0,
                paddingTop: 0.5,
            }}
        >
            {!isDrawerOpen ? (
                <Box sx={{display: "flex", flexDirection: "column"}}>
                    <Tooltip title={module.label} placement="right">
                        <IconButton
                            onClick={() => {
                                setOpenRoutes(!openRoutes);
                                handleNavigate(module?.route ?? "");
                            }}
                        >
                            {module.route === selectedPage
                                ? module.selectedIcon
                                : module.icon}
                        </IconButton>
                    </Tooltip>
                    <Collapse in={openRoutes} timeout="auto" unmountOnExit>
                        <List
                            component="div"
                            disablePadding
                            sx={{width: "100%", display: "flex", flexDirection: "column"}}
                        >
                            {module.routes.map((route, index) => (
                                <ListItem sx={{p: 0, paddingTop: 0.5}} key={index}>
                                    <Tooltip title={route.label} placement="right">
                                        <IconButton
                                            onClick={() => handleNavigate(route?.route ?? "")}
                                        >
                                            {route.route === selectedPage
                                                ? route.selectedIcon
                                                : route.icon}
                                        </IconButton>
                                    </Tooltip>
                                </ListItem>
                            ))}
                        </List>
                    </Collapse>
                </Box>
            ) : (
                <Box sx={{width: "100%"}}>
                    <ListItemButton
                        sx={{
                            display: "flex",
                            flexDirection: "row",
                            alignItems: "center",
                            justifyContent: "space-between",
                            width: "100%",
                            borderRadius: "15px",
                        }}
                        selected={module.route === selectedPage ? true : false}
                        color="#007EFB"
                        onClick={() => {
                            setOpenRoutes(!openRoutes);
                            handleNavigate(module?.route ?? "");
                        }}
                    >
                        <ListItemIcon>
                            {module.route === selectedPage
                                ? module.selectedIcon
                                : module.icon}
                        </ListItemIcon>
                        <ListItemText>
                            {!isDrawerOpen ? (
                                ""
                            ) : (
                                <Typography
                                    color={module.route === selectedPage ? "primary" : "text.primary"}>{module.label}</Typography>
                            )}
                        </ListItemText>
                        {module.expanded ? (
                            openRoutes ? (
                                <ExpandLess color="action"/>
                            ) : (
                                <ExpandMore color="action"/>
                            )
                        ) : (
                            ""
                        )}{" "}
                    </ListItemButton>
                    <Collapse
                        in={openRoutes}
                        timeout="auto"
                        unmountOnExit
                        sx={{width: "100%"}}
                    >
                        <List component="div" disablePadding sx={{width: "100%"}}>
                            {module.routes.map((route, index) => (
                                <ListItem
                                    sx={{width: "100%", p: 0, paddingLeft: 2, paddingTop: 0.5}}
                                    key={index}
                                >
                                    <ListItemButton
                                        sx={{
                                            display: "flex",
                                            flexDirection: "row",
                                            alignItems: "center",
                                            width: "100%",
                                            borderRadius: "15px",
                                            paddingRight: 0,
                                        }}
                                        selected={route.route === selectedPage ? true : false}
                                        onClick={() => handleNavigate(route?.route ?? "")}
                                    >
                                        <ListItemIcon>
                                            {route.route === selectedPage
                                                ? route.selectedIcon
                                                : route.icon}
                                        </ListItemIcon>
                                        <ListItemText>
                                            <Typography
                                                color={route.route === selectedPage ? "primary" : "text.primary"}
                                            >
                                                {route.label}
                                            </Typography>
                                        </ListItemText>
                                    </ListItemButton>
                                </ListItem>
                            ))}
                        </List>
                    </Collapse>
                </Box>
            )}
        </ListItem>
    );
};

export default MenuSide;
