import {ThemeProvider, createTheme} from "@mui/material";
import Root from "./shared/routes/Root";
import {useState, useMemo, createContext} from "react";
import {theme} from "./shared/themes/Theme.ts";

if (process.env.NODE_ENV) {
    console.log("Running in development mode");
}

const ColorModeContext = createContext({
    toggleColorMode: () => {
    }
});

const App = () => {
    const [mode, setMode] = useState(
        localStorage.getItem("website_theme") !== null
            ? localStorage.getItem("website_theme")
            : "dark"
    );

    localStorage.setItem("website_theme", mode);

    const colorMode = useMemo(() => ({
        toggleColorMode: () => {
            setMode((prevMode) => (prevMode === "light" ? "dark" : "light"));
        },
    }));

    const themeMode = useMemo(() => createTheme(theme(mode)), [mode]);

    return (
        <ColorModeContext.Provider value={colorMode}>
            <ThemeProvider theme={themeMode}>
                <Root ColorModeContext={ColorModeContext}/>
            </ThemeProvider>
        </ColorModeContext.Provider>
    );
};

export default App;
