import {Box} from "@mui/material";

class Icons {
    excelIcon = ({width, color}) => (
        <Box sx={{p: 0, m: 0}}>
            <img
                width={width}
                src={
                    color === "gray"
                        ? "data:image/png;base64,"
                        : "data:image/png;base64,"
                }
            />
        </Box>
    );

    logoPaymentBase64 = ({width}) => (
        <img
            width={width}
            src={
                "data:image/png;base64,"
            }
        />
    );
}

export const icons = new Icons();
