import {useTheme} from "@emotion/react";
import Brightness4Icon from "@mui/icons-material/Brightness4";
import Brightness7Icon from "@mui/icons-material/Brightness7";
import AddIcon from "@mui/icons-material/Add";
import {
    AppBar,
    Box,
    Button,
    Container,
    IconButton,
    Toolbar,
    Tooltip,
    Typography,
} from "@mui/material";
import {useLocation} from "react-router-dom";
import {useContext} from "react";

const AppBarDefault = ({onClickActionButton, ColorModeContext}) => {
    const selectedPage = useLocation().pathname.split("/");

    const theme = useTheme();
    const colorMode = useContext(ColorModeContext);

    function convertCamelCaseToNormal(str) {
        const convertedStr = str.replace(/([A-Z])/g, " $1");
        const finalStr = convertedStr.charAt(0).toUpperCase() + convertedStr.slice(1);
        return finalStr;
    }

    return (
        <AppBar position="sticky" elevation={0} sx={{color: "text.primary"}}>
            <Container
                maxWidth="100vw"
                sx={{backgroundColor: "background.default"}}
            >
                <Toolbar
                    disableGutters
                    sx={{display: "flex", justifyContent: "space-between"}}
                >
                    <Typography
                        sx={{
                            fontSize: "20pt",
                            fontWeight: "bold",
                        }}
                    >
                        {convertCamelCaseToNormal(selectedPage[selectedPage.length - 1])}
                    </Typography>
                    <Box sx={{display: "flex", gap: 2, alignItems: "center"}}>
                        <Tooltip title="Change theme">
                            <IconButton
                                onClick={colorMode.toggleColorMode}
                                color="primary"
                                size="large"
                            >
                                {theme.palette.mode === "dark" ? (
                                    <Brightness7Icon/>
                                ) : (
                                    <Brightness4Icon/>
                                )}
                            </IconButton>
                        </Tooltip>
                        {onClickActionButton?.function === "" ? (
                            ""
                        ) : (
                            <Button
                                variant="contained"
                                sx={{
                                    borderRadius: "10px",
                                    width: "10rem",
                                    justifyContent: "space-around",
                                    p: 1.3,
                                    height: "2.5rem",
                                }}
                                onClick={() => onClickActionButton.function()}
                            >
                                <Typography
                                    sx={{
                                        paddingLeft: 1,
                                    }}
                                >
                                    Criar novo
                                </Typography>
                                <AddIcon/>
                            </Button>
                        )}
                    </Box>
                </Toolbar>
            </Container>
        </AppBar>
    );
};

export default AppBarDefault;
