import ModalBase from "../../../shared/components/Modal/ModalBase";
import {useContext, useEffect, useState} from "react";
import PaymentModal from "../components/PaymentModal";
import {AppBarButtonContext} from "../../../shared/context/AppBarButtonContext";
import ModeEditOutlinedIcon from "@mui/icons-material/ModeEditOutlined";
import {paymentUseCases} from "../usecases/PaymentUseCases"
import {
    Box,
    CircularProgress,
    IconButton,
    Paper,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TablePagination,
    TableRow,
    Tooltip
} from "@mui/material"
import {Filters} from "../../../shared/entities/Filters";

const columns = [
    {
        id: 'date',
        label: 'Data',
        align: 'left',
    },
    {
        id: 'type',
        label: 'Tipo',
        align: 'left',
    },
    {
        id: 'value',
        label: 'Valor',
        align: 'right',
        format: (value) => value.toLocaleString('pt-BR'),
    },
    {
        id: 'totalSpent',
        label: 'Total gasto',
        align: 'right',
        format: (value) => value.toLocaleString('pt-BR'),
    },
    {
        id: 'description',
        label: 'Descrição',
        align: 'left',
        maxWidth: 150,
    },
    {
        id: 'action',
        label: "Ação",
        align: "center",
        value: "action",
        type: "action",
    }
];

function PaymentList() {
    const [show, setShow] = useState(false);
    const appBarButton = useContext(AppBarButtonContext);
    const [changed, setChanged] = useState(true);
    const [filters, setFilters] = useState(new Filters(1, 10, "", "asc", [], 0));
    const [page, setPage] = useState({
        page: 0,
        numberPages: 1,
        total: 1,
    });
    const [payments, setPaymentsList] = useState([])

    const handleReloadPage = () => {
        setChanged(!changed);
    };

    const handleModalPayment = () => {
        setShow(!show)
    }

    useEffect(() => {
        const paymentList = async () => {
            return await paymentUseCases.listPayments(filters)
        }
        paymentList().then((response) => {
            console.log(response?.data)
            setPaymentsList(response?.data?.payments ?? []);
            setPage({
                page: response?.data?.page-1 ?? 0,
                numberPages: response?.data?.numberPages ?? 1,
                total: response?.data?.total ?? 1,
            });
        });
    }, [filters, changed])

    useEffect(() => {
        appBarButton.changeActionAppBarButtonOnClick({
            function: () => handleModalPayment("", handleReloadPage),
        });

        document.title = "Alex | Payment";
    }, [show, changed]);

    const handleChangePage = (event, newPage) => {
        setPage({
            page: newPage ?? 1,
            numberPages: page.numberPages ?? 1,
            total: page.total ?? 1,
        });
    };

    const handleSubmit = (evt, payment) => {
        evt.preventDefault()

    }

    return (
        <Box sx={{margin: "2% 3% 3% 3%"}}>
            <ModalBase formName="payment-form" title="Criar pagamento" onClose={handleModalPayment} show={show}>
                <PaymentModal formName="payment-form" handleSubmit={handleSubmit}/>
            </ModalBase>
            <Paper>
                <TableContainer>
                    <Table stickyHeader aria-label="sticky table">
                        <TableHead>
                            <TableRow>
                                {columns.map((column) => (
                                    <TableCell
                                        key={column.id}
                                        align={column.align}
                                        style={{minWidth: column.minWidth, maxWidth: column.maxWidth}}
                                    >
                                        {column.label}
                                    </TableCell>
                                ))}
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {payments.map((value, index) => (
                                <TableBodyLines
                                    index={index}
                                    values={value}
                                    handleReloadPage={handleReloadPage}
                                    handleModalPayment={handleModalPayment}
                                />
                            ))}
                        </TableBody>
                    </Table>
                </TableContainer>
                <TablePagination
                    rowsPerPageOptions={[]}
                    component="div"
                    count={page.total ?? 1}
                    rowsPerPage={filters.rowsPerPage}
                    page={page.page ?? 1}
                    onPageChange={handleChangePage}
                />
            </Paper>
        </Box>
    );
}

const TableBodyLines = ({index, values, handleReloadPage, handleModalPayment}) => {
    const [loading, setLoading] = useState(false);

    const handleTimeOut = () => {
        setLoading(true);
        const reload = async () => {
            await handleReloadPage();
        };
        reload().then(() => {
            setTimeout(() => setLoading(false), 1000);
        });
    };

    return (
        <TableRow key={index} hover>
            <TableCell
                size="small"
                sx={{
                    overflow: "hidden",
                    whiteSpace: "nowrap",
                    textOverflow: "ellipsis",
                }}
            >
                {values?.date ?? ""}
            </TableCell>
            <TableCell
                size="small"
                sx={{
                    overflow: "hidden",
                    whiteSpace: "nowrap",
                    textOverflow: "ellipsis",
                }}
            >
                {values?.type?.label ?? ""}
            </TableCell>
            <TableCell
                size="small"
                sx={{
                    overflow: "hidden",
                    whiteSpace: "nowrap",
                    textOverflow: "ellipsis",
                }}
            >
                {values?.value ?? ""}
            </TableCell>
            <TableCell
                size="small"
                sx={{
                    overflow: "hidden",
                    whiteSpace: "nowrap",
                    textOverflow: "ellipsis",
                }}
            >
                {values?.totalSpent ?? ""}
            </TableCell>
            <TableCell
                size="small"
                sx={{
                    overflow: "hidden",
                    whiteSpace: "nowrap",
                    textOverflow: "ellipsis",
                }}
            >
                {values?.description ?? ""}
            </TableCell>
            <TableCell size="small" align="center">
                {loading ? (
                    <Tooltip title="">
                        <IconButton>
                            <CircularProgress size={20}/>
                        </IconButton>
                    </Tooltip>
                ) : (
                    <Tooltip title="Editar pagamento" placement="left">
                        <IconButton
                            onClick={() =>
                                handleModalPayment(values?.uuid ?? "", handleTimeOut)
                            }
                        >
                            <ModeEditOutlinedIcon color="primary"/>
                        </IconButton>
                    </Tooltip>
                )}
            </TableCell>
        </TableRow>
    );
};

export default PaymentList