import { OutlinedInput, TextField } from "@mui/material";
import FormControl from '@mui/material/FormControl';
import InputLabel from '@mui/material/InputLabel';
import MenuItem from '@mui/material/MenuItem';
import Select from '@mui/material/Select';
import { Box } from "@mui/system";
import { DatePicker, LocalizationProvider, ptBR } from "@mui/x-date-pickers";
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { useState } from "react";
import NumberFormatCustom from "../../../shared/components/NumberFormatCustom.js";
import { Payment } from "../entities/Payment.js";
import dayjs from "dayjs";

function PaymentModal(
    props,
) {
    const localeTextBR = ptBR.components.MuiLocalizationProvider.defaultProps.localeText;
    const [payment, setPayment] = useState(new Payment("", undefined, undefined, "", dayjs()));

    const handleDateChange = (date) => {
        setPayment((payment) => ({
            ...payment,
            date: date,
        }));
    };

    const handleTypeChange = (type) => {
        setPayment((payment) => ({
            ...payment,
            type: type,
        }));
    };

    const handleValueChange = (value) => {
        setPayment((payment) => ({
            ...payment,
            value: value,
        }));
    };

    const handleDescriptionChange = (description) => {
        setPayment((payment) => ({
            ...payment,
            description: description,
        }));
    };

    return (
        <form id={props.formName} onSubmit={(evt) => { props.handleSubmit(evt, payment) }}>
            <Box sx={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                <Box sx={{ display: "flex", gap: "5px", height: "4rem", marginTop: "5px" }}>
                    <LocalizationProvider dateAdapter={AdapterDayjs} localeText={localeTextBR}>
                        <DatePicker
                            sx={{ width: "100%" }}
                            label="Data"
                            format="DD/MM/YYYY"
                            value={payment.date ?? ""}
                            onChange={(evt) => { handleDateChange(evt.target.value) }}
                            name="date"
                            renderInput={(params) => (
                                <TextField
                                    sx={{ width: "15%" }}
                                    variant="outlined"
                                    inputProps={{ ...params.inputProps, placeholder: "dd/mm/yyyy" }}
                                />
                            )}
                        />
                    </LocalizationProvider>
                </Box>
                <Box sx={{ display: "flex", gap: "5px", height: "4rem" }}>
                    <FormControl variant="outlined" fullWidth>
                        <InputLabel id="payment-type">Tipo de recebimento</InputLabel>
                        <Select
                            labelId="payment-type"
                            id="payment-type"
                            name="type"
                            value={payment.type ?? ""}
                            label="Tipo de recebimento"
                            onChange={(evt) => { handleTypeChange(evt.target.value) }}
                        >
                            <MenuItem value={1}>Salário</MenuItem>
                            <MenuItem value={2}>VR</MenuItem>
                            <MenuItem value={3}>Outros</MenuItem>
                        </Select>
                    </FormControl>
                    <FormControl fullWidth sx={{ height: "4rem" }}>
                        <InputLabel htmlFor="payment-value">Valor</InputLabel>
                        <OutlinedInput
                            id="payment-value"
                            label="Valor"
                            name="value"
                            value={payment.value}
                            onChange={(evt) => { handleValueChange(evt.target.value) }}
                            inputComponent={NumberFormatCustom}
                        />
                    </FormControl>
                </Box>
                <Box sx={{ display: "flex", gap: "5px" }}>
                    <TextField
                        name="description"
                        sx={{ width: "100%" }}
                        multiline
                        rows={4}
                        value={payment.description}
                        onChange={(evt) => { handleDescriptionChange(evt.target.value) }}
                        placeholder="Descrição"
                        variant="outlined" />
                </Box>
            </Box>
        </form>
    )
}


export default PaymentModal