import http from "../../../HttpHelper";

class PaymentRepository {
    async listPayments(filters) {
        const parameters = `page=${filters.page}&size=${
            filters.rowsPerPage
        }&orderBy=${
            filters.orderBy === "" ? "description" : filters.orderBy
        }&sortBy=${filters.sort}`;
        const filtersList = `${
            filters.filters.length > 0
                ? filters.filters.map((filter) => {
                    if (filter.columnPopover !== "" && filter.valueFilter !== "") {
                        return (
                            "&filter=(" +
                            filter.columnPopover +
                            ":" +
                            filter.valueFilter +
                            ")"
                        );
                    }
                })
                : ""
        }`;
        try {
            return await http.get(
                `/payment?${parameters}${
                    filtersList !== "" ? filtersList.replaceAll(",", "") : ""
                }`
            );
        } catch (error) {
            return error;
        }
    }
}

export const paymentRepository = new PaymentRepository()