import {BrowserRouter, Route, Routes} from "react-router-dom";
import PaymentList from "../../core/payments/pages/Payment";
import DefaultPage from "../components/DeufaultPage";
import Login from "../../core/user/pages/login/Login";
import ResetPassword from "../../core/user/pages/resetpassword/ResetPassword";
import ChangePasswordLink from "../../core/user/pages/changepassword/ChangePasswordLink";
import RequireAuth from "../../core/user/components/RequireAuth";

const Root = ({ColorModeContext}) => {
    return (
        <BrowserRouter basename="/web">
            <Routes>
                <Route path="login" element={<Login/>}/>
                <Route path="resetPassword" element={<ResetPassword/>}/>
                <Route path="changePasswordLink" element={<ChangePasswordLink/>}/>
                <Route element={<RequireAuth/>}>
                    <Route
                        path="/"
                        element={<DefaultPage ColorModeContext={ColorModeContext}/>}
                    >
                        <Route path="payment" element={<PaymentList/>}/>
                    </Route>
                </Route>
            </Routes>
        </BrowserRouter>
    );
};

export default Root;
